WITH exploded AS (SELECT id, service, host, level, status_code, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) x AS attr_key, value) SELECT id, service, host, level, status_code, attr_key, NTILE(3) OVER (PARTITION BY level, attr_key ORDER BY status_code, id, attr_key) AS status_code_bucket, NTILE(5) OVER (PARTITION BY level ORDER BY status_code DESC, id, attr_key) AS status_code_bucket_2, AVG(status_code) OVER w_running AS status_code_avg_2_prior FROM exploded WINDOW w_running AS (PARTITION BY service ORDER BY status_code, id, attr_key ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING)
